new file mode 100644
index 0000000..ce3468c
--- /dev/null
+++ b/test/release-runner.test.js
@@ -0,0 +1,92 @@
+const assert = require('assert');
+const fs = require('fs');
+const os = require('os');
+const path = require('path');
+
+const runner = require('../scripts/release-runner.js');
+
+let passed = 0;
+function test(name, fn) {
+  fn();
+  passed += 1;
+  console.log(`ok - ${name}`);
+}
+
+function withTempDirectory(fn) {
+  const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'openvela-release-runner-test-'));
+  try {
+    fn(directory);
+  } finally {
+    fs.rmSync(directory, { recursive: true, force: true });
+  }
+}
+
+test('非 ASCII 工作路径才启用发布暂存', () => {
+  assert.strictEqual(runner.needsAsciiStaging('C:\\work\\openvela'), false);
+  assert.strictEqual(runner.needsAsciiStaging('F:\\项目\\openvela'), true);
+});
+
+test('暂存输入保留源码、可选签名和根配置，跳过构建产物', () => {
+  withTempDirectory((projectRoot) => {
+    for (const entry of ['src', 'sign', 'config', 'build', 'dist', 'node_modules']) {
+      fs.mkdirSync(path.join(projectRoot, entry));
+    }
+    for (const file of ['package.json', 'package-lock.json', '.npmrc', 'README.md']) {
+      fs.writeFileSync(path.join(projectRoot, file), file);
+    }
+
+    assert.deepStrictEqual(runner.projectEntries(projectRoot), [
+      '.npmrc',
+      'README.md',
+      'config',
+      'package-lock.json',
+      'package.json',
+      'sign',
+      'src',
+    ]);
+  });
+});
+
+test('仅接受非空正式 RPK 并排除 debug 包', () => {
+  withTempDirectory((dist) => {
+    fs.writeFileSync(path.join(dist, 'com.openvela.wristrhythm.debug.1.0.0.rpk'), 'debug');
+    fs.writeFileSync(path.join(dist, 'com.openvela.wristrhythm.release.1.0.0.rpk'), 'release');
+
+    assert.strictEqual(
+      path.basename(runner.findReleaseArtifact(dist)),
+      'com.openvela.wristrhythm.release.1.0.0.rpk',
+    );
+
+    fs.truncateSync(path.join(dist, 'com.openvela.wristrhythm.release.1.0.0.rpk'), 0);
+    assert.throws(() => runner.findReleaseArtifact(dist), /non-empty release RPK/);
+  });
+});
+
+test('发布前移除确切的旧正式 RPK，防止将其当作新产物', () => {
+  withTempDirectory((projectRoot) => {
+    const sourceDirectory = path.join(projectRoot, 'src');
+    const distDirectory = path.join(projectRoot, 'dist');
+    fs.mkdirSync(sourceDirectory);
+    fs.mkdirSync(distDirectory);
+    fs.writeFileSync(path.join(sourceDirectory, 'manifest.json'), JSON.stringify({
+      package: 'com.openvela.wristrhythm',
+      versionName: '1.0.0',
+    }));
+    const expectedArtifact = path.join(distDirectory, 'com.openvela.wristrhythm.release.1.0.0.rpk');
+    fs.writeFileSync(expectedArtifact, 'stale-release');
+
+    assert.strictEqual(runner.prepareReleaseArtifact(projectRoot), expectedArtifact);
+    assert.strictEqual(fs.existsSync(expectedArtifact), false);
+    assert.throws(() => runner.findExpectedReleaseArtifact(projectRoot), /non-empty expected release RPK/);
+
+    fs.writeFileSync(expectedArtifact, 'fresh-release');
+    assert.strictEqual(runner.findExpectedReleaseArtifact(projectRoot), expectedArtifact);
+  });
+});
+
+test('工具链记录构建错误时发布失败，即使退出码为零', () => {
+  assert.strictEqual(runner.hasReleaseFailure('ERROR:  build error , Error: signing failed'), true);
+  assert.strictEqual(runner.hasReleaseFailure('✅ [toolkit]: build success'), false);
+});
+
+console.log(`\n${passed} release runner tests passed`);
diff --git a/test/runtime.test.js b/test/runtime.test.js
new file mode 100644
index 0000000..88245a9
--- /dev/null
+++ b/test/runtime.test.js
@@ -0,0 +1,91 @@
+const assert = require('assert');
+const clock = require('../src/pages/index/session-clock.js');
+const subscriptions = require('../src/pages/index/subscription-lifecycle.js');
+const reactive = require('../src/pages/index/reactive.js');
+
+let passed = 0;
+function test(name, fn) {
+  fn();
+  passed += 1;
+  console.log(`ok - ${name}`);
+}
+
+test('可暂停时钟只累计前台有效时间', () => {
+  let state = clock.createClock(60000, 1000);
+  assert.strictEqual(clock.elapsedMs(state, 11000), 10000);
+  state = clock.pauseClock(state, 11000);
+  assert.strictEqual(clock.elapsedMs(state, 31000), 10000);
+  state = clock.resumeClock(state, 31000);
+  assert.strictEqual(clock.elapsedMs(state, 36000), 15000);
+  assert.strictEqual(clock.remainingSeconds(state, 36000), 45);
+});
+
+test('重复暂停和恢复保持幂等', () => {
+  const initial = clock.createClock(30000, 0);
+  const paused = clock.pauseClock(initial, 5000);
+  assert.deepStrictEqual(clock.pauseClock(paused, 9000), paused);
+  const resumed = clock.resumeClock(paused, 15000);
+  assert.deepStrictEqual(clock.resumeClock(resumed, 18000), resumed);
+  assert.strictEqual(clock.elapsedMs(resumed, 20000), 10000);
+});

+
+test('时钟在边界完成且剩余值不为负数', () => {
+  const state = clock.createClock(30000, 1000);
+  assert.strictEqual(clock.isComplete(state, 30999), false);
+  assert.strictEqual(clock.isComplete(state, 31000), true);
+  assert.strictEqual(clock.remainingMs(state, 32000), 0);
+});
+
+test('呼吸训练在完成边界恢复时不重启计时器', () => {
+  const state = clock.createClock(60000, 1000);
+  assert.strictEqual(clock.shouldScheduleInterval(state, 60999), true);
+  assert.strictEqual(clock.shouldScheduleInterval(state, 61000), false);
+});
+
+test('拳击恢复后从下一个节拍开始且不补发后台目标', () => {
+  assert.strictEqual(clock.nextBeatAfterResume(5000, 1000), 6000);
+  assert.strictEqual(clock.nextBeatAfterResume(5500, 1200), 6000);
+  assert.strictEqual(clock.nextBeatAfterResume(0, 1000), 1000);
+});
+
+test('显示时只计划尚未激活的健康订阅', () => {
+  let state = subscriptions.createSubscriptionState([0, 9]);
+  assert.deepStrictEqual(subscriptions.typesToSubscribe(state), [0, 9]);
+  state = subscriptions.markSubscribed(state, 0);
+  state = subscriptions.markSubscribed(state, 9);
+  assert.deepStrictEqual(subscriptions.typesToSubscribe(state), []);
+});
+
+test('隐藏时只取消实际激活的类型且重复取消幂等', () => {
+  let state = subscriptions.createSubscriptionState([0, 9]);
+  state = subscriptions.markSubscribed(state, 0);
+  assert.deepStrictEqual(subscriptions.typesToUnsubscribe(state), [0]);
+  state = subscriptions.markUnsubscribed(state, 0);
+  assert.deepStrictEqual(subscriptions.typesToUnsubscribe(state), []);
+  assert.deepStrictEqual(subscriptions.markUnsubscribed(state, 0), state);
+});
+
+test('失败类型从激活集合移除并可在下次显示重试', () => {
+  let state = subscriptions.createSubscriptionState([0, 9]);
+  state = subscriptions.markSubscribed(state, 0);
+  state = subscriptions.markSubscribed(state, 9);
+  state = subscriptions.markUnsubscribed(state, 9);
+  assert.deepStrictEqual(subscriptions.typesToSubscribe(state), [9]);
+});
+
+test('相同显示值不会重复触发响应式 setter', () => {
+  let writes = 0;
+  let stored = '30';
+  const target = {};
+  Object.defineProperty(target, 'remaining', {
+    get() { return stored; },
+    set(value) { writes += 1; stored = value; },
+  });
+
+  assert.strictEqual(reactive.writeIfChanged(target, 'remaining', '30'), false);
+  assert.strictEqual(reactive.writeIfChanged(target, 'remaining', '29'), true);
+  assert.strictEqual(reactive.writeIfChanged(target, 'remaining', '29'), false);
+  assert.strictEqual(writes, 1);
+});
+
+console.log(`\n${passed} runtime tests passed`);

import health from '@service.health';
import core from './health-core.js';

export const DATA_TYPES = health.DATA_TYPES;

export function getRecent(dataTypes) {
  return health
    .getRecentSamples({ dataTypes })
    .then((list) => core.normalizeRecent(list))
    .catch(() => []);
}

export function subscribe(dataType, onSample, onError) {
  health.subscribeSample({
    dataType,
    callback: (sample) => {
      const normalized = core.normalizeSample(dataType, sample);
      if (normalized) onSample(normalized);
    },
    fail: (data, code) => {
      if (onError) onError(core.normalizeError(code));
    },
  });
}

export function unsubscribe(dataType) {
  health.unsubscribeSample({ dataType });
}


import sensor from '@system.sensor';

export function subscribeAccelerometer(onSample, onError) {
  try {
    sensor.subscribeAccelerometer({
      interval: 'game',
      callback: (sample) => {
        onSample({ x: sample.x, y: sample.y, z: sample.z });
      },
      fail: (message, code) => {
        if (onError) onError({ message, code });
      },
    });
  } catch (error) {
    if (onError) onError({ message: error.message, code: 200 });
  }
}

export function unsubscribeAccelerometer() {
  try {
    sensor.unsubscribeAccelerometer();
  } catch (error) {
    console.log('取消加速度订阅失败', error.message);
  }
}

