44: function scorePunch(punchAt, beatAt) {
45:   const difference = Math.abs(punchAt - beatAt);
46:   if (difference <= 120) return { points: 100, grade: 'perfect' };
47:   if (difference <= 250) return { points: 70, grade: 'good' };
48:   if (difference <= HIT_WINDOW_MS) return { points: 40, grade: 'hit' };
49:   return { points: 0, grade: 'miss' };
50: }
